const batchSize = 25;

function parseObject(value) {
  if (value && typeof value === 'object') {
    return value;
  }

  if (typeof value !== 'string' || !value.trim()) {
    return {};
  }

  try {
    return JSON.parse(value);
  } catch {
    return {};
  }
}

function normalizeArray(value) {
  if (Array.isArray(value)) {
    return value
      .map((entry) => String(entry || '').trim())
      .filter(Boolean);
  }

  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);

      if (Array.isArray(parsed)) {
        return parsed
          .map((entry) => String(entry || '').trim())
          .filter(Boolean);
      }
    } catch {
      return value
        .split(',')
        .map((entry) => entry.trim())
        .filter(Boolean);
    }
  }

  return [];
}

function parseSalaryAmount(rawValue, hasThousandsMarker) {
  let number = Number(
    String(rawValue || '')
      .replace(/\u00a0/g, ' ')
      .replace(/\s/g, '')
      .replace(',', '.')
  );

  if (!Number.isFinite(number)) {
    return null;
  }

  if (hasThousandsMarker && number < 1000) {
    number *= 1000;
  }

  if (number < 10000 || number > 2000000) {
    return null;
  }

  return Math.round(number);
}

function extractUpperBounds(text) {
  const source = String(text || '')
    .replace(/\u00a0/g, ' ')
    .toLowerCase();

  const values = [];

  const rangePattern =
    /(\d[\d\s]*(?:[.,]\d+)?)\s*((?:тыс(?:\.|яч[аи]?)?|k))?\s*(?:-|–|—|до)\s*(\d[\d\s]*(?:[.,]\d+)?)\s*((?:тыс(?:\.|яч[аи]?)?|k))?(?:\s*(?:(?:руб(?:\.|ля|лей)?|rur)|₽))?/gi;

  for (const match of source.matchAll(rangePattern)) {
    const hasThousands = Boolean(match[2] || match[4]);

    const upper = parseSalaryAmount(
      match[3],
      Boolean(match[4]) || hasThousands
    );

    if (upper !== null) {
      values.push(upper);
    }
  }

  const upperLimitPattern =
    /(?:до|максимум|max)\s*(\d[\d\s]*(?:[.,]\d+)?)\s*((?:тыс(?:\.|яч[аи]?)?|k))?(?:\s*(?:(?:руб(?:\.|ля|лей)?|rur)|₽))?/gi;

  for (const match of source.matchAll(upperLimitPattern)) {
    const upper = parseSalaryAmount(match[1], Boolean(match[2]));

    if (upper !== null) {
      values.push(upper);
    }
  }

  return values;
}

function extractSalaryContexts(descriptionValue) {
  const description = String(descriptionValue || '')
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .toLowerCase();

  const markerPattern =
    /зарплат|заработн|оклад|доход|оплат[аы]|вознагражден|вилк/gi;

  const contexts = [];

  for (const match of description.matchAll(markerPattern)) {
    const start = Math.max(0, match.index - 60);
    const end = Math.min(description.length, match.index + 220);

    contexts.push(description.slice(start, end));
  }

  return contexts;
}

function extractKnownSalaryUpperBound(
  salaryValue,
  descriptionValue
) {
  const salary = String(salaryValue || '')
    .replace(/\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .toLowerCase()
    .trim();

  const salaryIsUnknown =
    !salary ||
    /не указана|не указан|по договоренности|обсуждается/.test(
      salary
    );

  if (!salaryIsUnknown) {
    const unsupportedCurrency =
      /usd|eur|доллар|евро|\$|€/.test(salary) &&
      !/(?:руб|rur|₽)/.test(salary);

    if (unsupportedCurrency) {
      return null;
    }

    if (
      /за час|в час|почасов|за смену|за проект/.test(salary)
    ) {
      return null;
    }

    const isLowerBoundOnly =
      /^\s*от\s*\d/i.test(salary) &&
      !/до\s*\d/i.test(salary) &&
      !/(?:-|–|—)\s*\d/i.test(salary);

    if (isLowerBoundOnly) {
      return null;
    }

    const structuredBounds = extractUpperBounds(salary);

    if (structuredBounds.length > 0) {
      return Math.max(...structuredBounds);
    }

    const fixedPattern =
      /(\d[\d\s]*(?:[.,]\d+)?)\s*((?:тыс(?:\.|яч[аи]?)?|k))?(?:\s*(?:(?:руб(?:\.|ля|лей)?|rur)|₽))/gi;

    const fixedValues = [];

    for (const match of salary.matchAll(fixedPattern)) {
      const fixed = parseSalaryAmount(
        match[1],
        Boolean(match[2])
      );

      if (fixed !== null) {
        fixedValues.push(fixed);
      }
    }

    if (fixedValues.length > 0) {
      return Math.max(...fixedValues);
    }

    return null;
  }

  const contextualBounds = [];

  for (const context of extractSalaryContexts(descriptionValue)) {
    contextualBounds.push(...extractUpperBounds(context));

    const fixedPattern =
      /(\d[\d\s]*(?:[.,]\d+)?)\s*((?:тыс(?:\.|яч[аи]?)?|k))?(?:\s*(?:(?:руб(?:\.|ля|лей)?|rur)|₽))/gi;

    for (const match of context.matchAll(fixedPattern)) {
      const fixed = parseSalaryAmount(
        match[1],
        Boolean(match[2])
      );

      if (fixed !== null) {
        contextualBounds.push(fixed);
      }
    }
  }

  if (contextualBounds.length === 0) {
    return null;
  }

  return Math.max(...contextualBounds);
}

const hardBlockingReasons = new Set([
  'salary_below_minimum',
  'vacancy_archived',
  'vacancy_unavailable',
]);

const decisionPriority = {
  recommend: 0,
  review: 1,
  reject: 2,
};

const eligible = [];

for (const item of $input.all()) {
  const vacancy = { ...item.json };
  const analysis = parseObject(vacancy.analysis_json);

  const evaluation =
  analysis.evaluation &&
  typeof analysis.evaluation === 'object'
    ? analysis.evaluation
    : analysis;

  const recommendedResume = String(
    vacancy.recommended_resume ||
      evaluation.recommended_resume ||
      'none'
  );

  if (
    recommendedResume !== 'ai_automation' &&
    recommendedResume !== 'it_infrastructure'
  ) {
    continue;
  }

  if (
    typeof vacancy.cover_letter === 'string' &&
    vacancy.cover_letter.trim()
  ) {
    continue;
  }

  const blockingReasons = [
    ...new Set([
      ...normalizeArray(evaluation.blocking_reasons),
      ...normalizeArray(vacancy.blocking_reasons),
    ]),
  ];

  const salaryUpperBound = extractKnownSalaryUpperBound(
    vacancy.salary,
    vacancy.description_text
  );

  const minimumSalary =
    recommendedResume === 'ai_automation' ? 120000 : 100000;

  if (
    salaryUpperBound !== null &&
    salaryUpperBound < minimumSalary &&
    !blockingReasons.includes('salary_below_minimum')
  ) {
    blockingReasons.push('salary_below_minimum');
  }

  const hasHardBlocker = blockingReasons.some((reason) =>
    hardBlockingReasons.has(reason)
  );

  if (hasHardBlocker) {
    continue;
  }

  const score = Number.isFinite(Number(vacancy.score))
    ? Number(vacancy.score)
    : Number(evaluation.score || 0);

  const decision = String(
    evaluation.decision ||
      (score >= 75 ? 'recommend' : score >= 60 ? 'review' : 'reject')
  );

  vacancy.letter_analysis = evaluation;
  vacancy.letter_recommended_resume = recommendedResume;
  vacancy.letter_score = score;
  vacancy.letter_decision = decision;
  vacancy.letter_blocking_reasons = blockingReasons;
  vacancy.detected_salary_upper_bound = salaryUpperBound;

  eligible.push(vacancy);
}

eligible.sort((a, b) => {
  const decisionDifference =
    (decisionPriority[a.letter_decision] ?? 3) -
    (decisionPriority[b.letter_decision] ?? 3);

  if (decisionDifference !== 0) {
    return decisionDifference;
  }

  if (b.letter_score !== a.letter_score) {
    return b.letter_score - a.letter_score;
  }

  return String(b.published_at || '').localeCompare(
    String(a.published_at || '')
  );
});

